public class InnerOptimizationJobOptimizationConfigFactory(Action<Humidifier.SageMaker.OptimizationJobTypes.OptimizationConfig> factoryAction = null) : SubResourceFactory<Humidifier.SageMaker.OptimizationJobTypes.OptimizationConfig>
{

    internal InnerOptimizationJobModelShardingConfigFactory ModelShardingConfigFactory { get; set; }

    internal InnerOptimizationJobModelQuantizationConfigFactory ModelQuantizationConfigFactory { get; set; }

    internal InnerOptimizationJobModelCompilationConfigFactory ModelCompilationConfigFactory { get; set; }

    protected override Humidifier.SageMaker.OptimizationJobTypes.OptimizationConfig Create()
    {
        var optimizationConfigResult = CreateOptimizationConfig();
        factoryAction?.Invoke(optimizationConfigResult);

        return optimizationConfigResult;
    }

    private Humidifier.SageMaker.OptimizationJobTypes.OptimizationConfig CreateOptimizationConfig()
    {
        var optimizationConfigResult = new Humidifier.SageMaker.OptimizationJobTypes.OptimizationConfig();

        return optimizationConfigResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.OptimizationJobTypes.OptimizationConfig result)
    {
        base.CreateChildren(result);

        result.ModelShardingConfig ??= ModelShardingConfigFactory?.Build();
        result.ModelQuantizationConfig ??= ModelQuantizationConfigFactory?.Build();
        result.ModelCompilationConfig ??= ModelCompilationConfigFactory?.Build();
    }

} // End Of Class

